update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/maintenance-industrielle-metz/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance industrielle à Metz et en Moselle","mecanisme":"À Metz, nous ne parlons pas au conditionnel. Depuis mai 2024, 10 techniciens polyvalents tiennent le site logistique ETZ 2 une semaine par mois, par créneaux de 8 heures. Le même dispositif s''applique aux laminoirs, aux presses et aux parcs d''usinage du sillon mosellan. Il repose sur notre hub de techniciens de Metz.","cta":"Demander une intervention à Metz","telephone":"04 78 33 72 05","phraseDelai":"Un chargé d''affaires vous rappelle dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7, en option, prend le relais la nuit, le week-end et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"10","libelle":"techniciens polyvalents sur le site ETZ 2 à Metz, une semaine par mois, depuis mai 2024"},{"valeur":"18 à 25","libelle":"techniciens déployés sur plusieurs sites du Grand Est depuis juin 2023"},{"valeur":"10 %","libelle":"des candidats franchissent l''entretien technique et comportemental, résultats communiqués"},{"valeur":"10","libelle":"hubs de techniciens en France, dont un à Metz, plus notre siège lyonnais et nos agences de Montréal, Dubaï et Madrid"}]},{"type":"probleme","punchline":"Un entraînement de laminoir claque en fin de poste. Le métal en cours refroidit dans la cage, et la reprise coûte plus cher que la panne elle-même.","puces":[{"accroche":"Le métal à chaud consomme les organes.","texte":"Roulements, transmissions, hydraulique de presse : l''usure va plus vite que le calendrier d''entretien standard."},{"accroche":"La cadence automobile ne tolère pas l''improvisation.","texte":"Robots, convoyeurs, machines-outils : chaque minute d''arrêt se répercute sur le poste suivant."},{"accroche":"Les sites chimiques imposent leur protocole.","texte":"Zones classées, consignation, permis de feu : l''accès se prépare, il ne s''improvise pas le jour de la panne."},{"accroche":"Le marché de l''emploi transfrontalier vide les équipes.","texte":"Vos techniciens partent, vos annonces restent ouvertes, et le préventif recule chaque mois."},{"accroche":"Le sillon mosellan s''étire sur des dizaines de kilomètres.","texte":"Un prestataire ancré sur une seule zone laisse l''autre moitié du bassin sans réponse."}]}]'::jsonb) where path = '/implantations/maintenance-industrielle-metz/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"offre","lignes":[{"prestation":{"accroche":"Maintenance des équipements de transformation du métal","texte":"laminoirs, fours, presses, traitement thermique, entraînements."},"benefice":"Les organes sensibles sont suivis au rythme réel de l''usure, pas à celui du catalogue."},{"prestation":{"accroche":"Renfort d''équipes sur site","texte":", du technicien unique à la dizaine d''intervenants sur plusieurs sites."},"benefice":"Vous absorbez une montée de cadence ou une transition industrielle sans recruter dans l''urgence."},{"prestation":{"accroche":"Techniciens habilités pour les sites à procédés continus","texte":", consignation et permis de feu systématiques."},"benefice":"L''accueil sécurité valide l''intervenant au lieu de le renvoyer."},{"prestation":{"accroche":"Couverture multi-technique","texte":"[mécanique](/expertises/mecanique/), [électrique](/expertises/electrique/), [automatisme](/expertises/automatisme/), [électromécanique](/expertises/electromecanique/), [hydraulique](/expertises/hydraulique/), [soudure et chaudronnerie](/expertises/soudure/)."},"benefice":"Une panne qui croise trois métiers mobilise une équipe, pas trois contrats."},{"prestation":{"accroche":"Automaticiens SIEMENS et Schneider, roboticiens ABB et Fanuc","texte":"en appui du terrain."},"benefice":"La compétence rare arrive quand la panne l''exige, sans attendre un prestataire spécialisé."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", mobilisée depuis notre hub de techniciens de Metz."},"benefice":"Un défaut de nuit ne se transforme pas en journée d''arrêt."}],"prose":[{"texte":"Pour les plateformes et entrepôts du sillon, voir notre pratique de la [maintenance des équipements logistiques](/secteurs/logistique/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation","texte":"équipement, symptôme, criticité, accès au site, habilitations exigées."},{"titre":"Nous vous rappelons dans l''heure","texte":"qualification du besoin, du profil et des pièces à anticiper."},{"titre":"Le cadre est écrit avant le départ","texte":"périmètre, conditions de chantier, chiffrage. Pas de poste surprise en fin de facture."},{"titre":"L''intervention suit votre protocole","texte":"accueil sécurité, plan de prévention, consignation, pré-visite quand l''accès l''impose."},{"titre":"La cause racine est cherchée après la remise en route","texte":"mesures, historique machine, conditions d''exploitation."},{"titre":"Le compte rendu est versé dans votre GMAO","texte":"constat, actions, pièces, organes à reprendre."}]},{"type":"garanties","puces":[{"accroche":"Un dispositif transposable, pas une promesse","texte":"le mode opératoire éprouvé sur un centre en continu à Metz s''applique à d''autres parcs, avec la même organisation par créneaux."},{"accroche":"Le profil présenté avant l''arrivée","texte":"10 % des candidats retenus après entretien technique et comportemental, résultats d''évaluation partagés."},{"accroche":"Aucun délai de route inventé","texte":"rappel dans l''heure aux horaires ouvrés, astreinte 24/24 et 7/7 en option. Le reste dépend de votre implantation exacte et se dit avant d''engager."}]},{"type":"cta","question":"Besoin d''un renfort technique sur un site mosellan avant la prochaine montée de cadence ?","bouton":"Demander une intervention à Metz","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/implantations/maintenance-industrielle-metz/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"10 techniciens polyvalents une semaine par mois sur le site ETZ 2, à Metz, depuis mai 2024","texte":"dispositif transposé d''un premier centre logistique en continu","lienLibelle":"Étude de cas AMAZON : démarrage d''un nouveau site","lienHref":"/preuves/amazon-nouveau-site/"},{"titre":"18 à 25 techniciens sur plusieurs sites du Grand Est depuis juin 2023","texte":"compétences apportées pour la transition vers le véhicule électrique","lienLibelle":"Étude de cas STELLANTIS : sites du Grand Est","lienHref":"/preuves/stellantis-grand-est/"},{"titre":"Un technicien intégré à temps plein sur un parc de centres d''usinage, de presses et de machines à commande numérique","texte":"fabrication de pièces de précision, 2025","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Six techniciens sur l''installation et la mise en production d''un nouveau parc machine","texte":"site automobile, à partir de janvier 2023","lienLibelle":"Étude de cas EATON : mise en production","lienHref":"/preuves/eaton-mise-en-production/"},{"titre":"Techniciens intégrés en 2025 pour sécuriser la maintenance des installations d''un équipementier automobile","texte":"réorganisation industrielle en cours","lienLibelle":"Étude de cas JTEKT : maintenance des installations","lienHref":"/preuves/jtekt/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment sur place, à Metz ?","reponse":"Oui, et c''est vérifiable : Metz est l''un de nos dix hubs de techniciens en France, et depuis mai 2024, 10 de nos techniciens tiennent le site ETZ 2 à Metz une semaine par mois, par créneaux de 8 heures. Derrière ce hub, notre siège à Lyon et nos agences de Montréal, Dubaï et Madrid. La question utile porte ensuite sur le technicien qui franchit votre portail. Son niveau, ses habilitations, son outillage, et la trace qu''il laisse dans votre GMAO."},{"question":"Quelles communes couvrez-vous en Moselle ?","reponse":"Metz et son agglomération, Thionville, Saint-Avold, Florange, le sillon mosellan et la Meurthe-et-Moselle jusqu''à Nancy. Au-delà, le réseau national prend le relais avec les mêmes méthodes et les mêmes comptes rendus."},{"question":"Intervenez-vous sur les équipements de métallurgie et d''usinage ?","reponse":"Oui : presses, laminoirs, fours, machines-outils, cellules robotisées. Réparation, préventif et remise en état, en atelier comme sur site, avec la traçabilité qu''attendent les donneurs d''ordre automobiles."},{"question":"Pouvez-vous absorber un pic sans que nous recrutions ?","reponse":"Oui. Nos dispositifs vont du technicien unique en résidence à plusieurs dizaines d''intervenants répartis sur des sites d''un même groupe. Le dimensionnement s''écrit avant, et il se révise à la baisse comme à la hausse."},{"question":"Que se passe-t-il si la panne tombe la nuit ?","reponse":"L''astreinte 24/24 et 7/7 prend l''appel et mobilise un technicien. Elle se souscrit en option du contrat, avec un circuit de priorités défini à l''avance. Sans astreinte, les demandes sont traitées aux horaires ouvrés, avec rappel dans l''heure."},{"question":"Comment tenez-vous un poste que nous n''arrivons pas à pourvoir ?","reponse":"Avec le [technicien en résidence](/offres/residence/). Un salarié Migen rejoint votre équipe, encadré par un référent. Prise de poste en 2 à 3 semaines, remplacement assuré en cas d''absence ou de départ."}]}]'::jsonb) where path = '/implantations/maintenance-industrielle-metz/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"ctaFinal","question":"Besoin de sécuriser une compétence que le bassin ne vous fournit plus ?","bouton":"Demander une intervention à Metz","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/maintenance-industrielle-metz/';
